import { LightningElement, api, track } from 'lwc';
import getOpenOpportunities from '@salesforce/apex/OpportunityController.getOpenOpportunities';

export default class OpenOpportunities extends LightningElement {
    @track isLoading = false;
    @track opportunities = null;
    @track errorMessage = '';

    private recordIdValue;
    private loading = false;

    @api get recordId() {
        return this.recordIdValue;
    }

    set recordId(value) {
        if (value && value !== this.recordIdValue) {
            this.recordIdValue = value;
            // If the value arrives before connectedCallback, start the initial call.
            this.loadOpportunities();
        }
    }

    connectedCallback() {
        if (!this.loading) {
            this.loadOpportunities();
        }
    }

    loadOpportunities = () => {
        if (this.loading || !this.recordId) {
            return;
        }

        this.loading = true;
        this.isLoading = true;
        this.errorMessage = '';
        this.opportunities = null;

        getOpenOpportunities({ accountId: this.recordId })
            .then((result) => {
                this.opportunities = result || [];
                this.errorMessage = '';
            })
            .catch((err) => {
                this.errorMessage = err?.body?.message || err?.message || 'An error occurred.';
                this.opportunities = null;
            })
            .finally(() => {
                this.loading = false;
                this.isLoading = false;
            });
    };

    handleRetry = () => {
        this.loadOpportunities();
    };

    get isEmpty() {
        return !this.isLoading && !this.errorMessage && Array.isArray(this.opportunities) && this.opportunities.length === 0;
    }

    get hasOpportunities() {
        return !this.isLoading && !this.errorMessage && Array.isArray(this.opportunities) && this.opportunities.length > 0;
    }
}
```

