```javascript
import { LightningElement, api } from 'lwc';

export default class TaskChecklist extends LightningElement {
    _heading;

    @api
    get heading() {
        return (this._heading || '').toUpperCase();
    }
    set heading(value) {
        this._heading = value;
    }

    @api
    get tasks() {
        return this.items;
    }
    set tasks(value) {
        if (Array.isArray(value)) {
